///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ElwExcelUpload
 * @description Elw Excel Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwExcelUpload",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=excelUpload",
        ref: "dma_ElwExcelUploadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name elwExcelUpload
 * @description elw Excel Upload 처리
 * @returns {void}
 * @hidden N
 */
scwin.elwExcelUpload = function () {
    const form = (document.subcomExcelForm || { elements: [] });
    if ($c.util.getComponent('upd_attachFile').getValue() == null || ($c.util.getComponent('upd_attachFile').getValue() == null ? '' : String($c.util.getComponent('upd_attachFile').getValue())) === '') {
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_attachFile').getValue())) {
            scwin.alertExcel("엑셀 파일만(xls) 업로드 가능합니다.");
            $("#upd_attachFile").replaceWith($("#upd_attachFile").clone(true));
            return;
        }
    }
    let statNm = (String(((dma_pageContext.get("ipt_pageGubun") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_pageGubun") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_pageGubun") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_pageGubun") ?? ""))));
    if (statNm === "subcom") {
        statNm = "자회사현황";
    } else {
        statNm = "종속회사현황";
    }
    scwin.confirmExcel(statNm + "을 업로드 하시겠습니까?");
};

/**
 * @method
 * @name checkFileType
 * @description check File Type 처리
 * @param {*} filePath filePath
 * @returns {void}
 * @hidden N
 */
scwin.checkFileType = function (filePath) {
    if (filePath == null || filePath === "") {
        return false;
    }
    const tfp = filePath.toLowerCase();
    if (tfp.indexOf(".xls") < 0 || tfp.substr(tfp.length - 4, 4) !== ".xls") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name alertExcel
 * @description alert Excel 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.alertExcel = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertExcelText')[0].innerText = msg;
    scwin.excelAlertMsg.setStyle("display", "");
};

/**
 * @method
 * @name closeAlertExcel
 * @description close Alert Excel 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeAlertExcel = function () {
    scwin.excelAlertMsg.setStyle("display", "none");
};

/**
 * @method
 * @name confirmExcel
 * @description confirm Excel 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.confirmExcel = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pConfirmExcelText')[0].innerText = msg;
    scwin.excelConfirmMsg.setStyle("display", "");
};

/**
 * @method
 * @name goSubmit
 * @description go Submit 처리
 * @returns {void}
 * @hidden N
 */
scwin.goSubmit = function () {
    $c.util.getComponent('ipt_SCREN_PROCES_TP_CD').setValue("02");
    $('#subcomExcelForm').submit();
    (($c.util.getComponent('upd_attachFile')) && ($c.util.getComponent('upd_attachFile')).setDisabled ? ($c.util.getComponent('upd_attachFile')).setDisabled(('disabled') === 'disabled' || ('disabled') === 'readonly' || ('disabled') === 'checked' ? true : ('disabled')) : void 0);
};

/**
 * @method
 * @name closeConfirmExcel
 * @description close Confirm Excel 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeConfirmExcel = function () {
    scwin.excelConfirmMsg.setStyle("display", "none");
};

/**
 * @method
 * @name resizeWindow
 * @description resize Window 처리
 * @param {*} win win
 * @returns {void}
 * @hidden N
 */
scwin.resizeWindow = function (win) {
    win.resizeTo(750, 350);
};
